#!/usr/bin/env python3
"""Interpret the generated action graph with mocked native Clock/HTTP actions."""

from copy import deepcopy
from contextlib import redirect_stderr
from datetime import datetime, timedelta
from io import StringIO
import json
import plistlib
import re
import subprocess
import sys
import tempfile
import unittest
from unittest.mock import patch
import zipfile
from zoneinfo import ZoneInfo

import generate

# AI: below section was generated by an AI
ZONE = ZoneInfo("Europe/Berlin")
NOW = datetime(2026, 11, 8, 22, 15, 0, 123000, tzinfo=ZONE)
BASE = "http://192.168.178.32"
RESULT_URL = generate.SYNC_PATH + "/result?job=7&boot=1234567890abcdef"
PROFILE = {"label": 'iPhone "light"', "rampMin": 30, "holdMin": 30, "fadeMin": 5,
           "snoozeMin": 10, "brightness": 180, "white": 220, "scene": "sunrise", "preset": 0}


def alarm(label="WLED Work", time="07:00", enabled=True, repeat=()):
    return {"Label": label, "Time": time, "Is Enabled": enabled, "Repeat": list(repeat)}


def configured(shortcut, live=1):
    """Apply import-question answers in memory, without importing into a user's library."""
    document = deepcopy(shortcut.document())
    for question in document["WFWorkflowImportQuestions"]:
        parameters = document["WFWorkflowActions"][question["ActionIndex"]]["WFWorkflowActionParameters"]
        parameters[question["ParameterKey"]] = BASE if question["ParameterKey"] == "WFTextActionText" else live
    return document


class Stop(Exception):
    pass


class Runtime:
    """Mock only the native adapters; execute the actual generated control-flow graph."""

    def __init__(self, document, alarms=(), now=NOW):
        self.actions = document["WFWorkflowActions"]
        self.alarms = list(alarms)
        self.now = now
        self.variables = {}
        self.outputs = {}
        self.messages = []
        self.output = None
        self.posts = []
        self.reads = []
        self.pending_polls = 0
        self.polls = 0
        self.read_delay = 0
        self.clock_error = False
        self.network_error = False
        self.cancel_alert = False
        self.receipt_url = RESULT_URL
        self.result_overrides = {}
        self.status_overrides = {}
        self.api_error = None
        self.last_body = {}
        self.ends, self.elses = {}, {}
        stack = []
        for index, action in enumerate(self.actions):
            parameters = action["WFWorkflowActionParameters"]
            if "WFControlFlowMode" not in parameters:
                continue
            group = parameters["GroupingIdentifier"]
            mode = parameters["WFControlFlowMode"]
            if mode == 0:
                stack.append((group, index))
            elif mode == 1:
                assert stack[-1][0] == group
                self.elses[stack[-1][1]] = index
            else:
                opened, start = stack.pop()
                assert opened == group
                self.ends[start] = index
        assert not stack

    def resolve(self, value):
        if isinstance(value, list):
            return [self.resolve(item) for item in value]
        if not isinstance(value, dict):
            return value
        kind = value.get("WFSerializationType")
        if kind == "WFTextTokenAttachment":
            return self.resolve(value["Value"])
        if kind == "WFTextTokenString":
            data = value["Value"]
            encoded = data["string"].encode("utf-16-le")
            replacements = []
            for location, reference in data.get("attachmentsByRange", {}).items():
                start, length = map(int, re.fullmatch(r"\{(\d+), (\d+)\}", location).groups())
                replacements.append((start, length, self.as_text(self.resolve(reference))))
            for start, length, replacement in sorted(replacements, reverse=True):
                encoded = encoded[:start * 2] + replacement.encode("utf-16-le") + encoded[(start + length) * 2:]
            return encoded.decode("utf-16-le")
        if kind == "WFDictionaryFieldValue":
            return {self.resolve(item["WFKey"]): self.resolve(item["WFValue"])
                    for item in value["Value"]["WFDictionaryFieldValueItems"]}
        if kind == "WFQuantityFieldValue":
            return self.resolve(value["Value"])
        if value.get("Type") == "Variable":
            result = self.resolve(value["Variable"]) if "Variable" in value else self.variables.get(value["VariableName"])
        elif value.get("Type") == "ActionOutput":
            result = self.outputs.get(value["OutputUUID"])
        else:
            return {key: self.resolve(item) for key, item in value.items()}
        for modifier in value.get("Aggrandizements", []):
            if modifier["Type"] == "WFPropertyVariableAggrandizement":
                result = result.get(modifier["PropertyName"]) if isinstance(result, dict) else None
            else:
                raise AssertionError("Unexpected mock coercion")
        return result

    @staticmethod
    def as_text(value):
        if value is None:
            return ""
        if isinstance(value, bool):
            return "true" if value else "false"
        if isinstance(value, (list, dict)):
            return json.dumps(value, ensure_ascii=False)
        return str(value)

    def date(self, value):
        if isinstance(value, datetime):
            return value
        if re.fullmatch(r"[0-9]{2}:[0-9]{2}", str(value)):
            value = self.now.strftime("%Y-%m-%dT") + value + ":00"
        result = datetime.fromisoformat(value)
        if result.tzinfo is None:
            result = result.replace(tzinfo=ZONE)
        # This models a parser which normalizes a nonexistent local time.
        return result.astimezone(ZoneInfo("UTC")).astimezone(ZONE)

    def format_date(self, value, pattern):
        date = self.date(value)
        if pattern == generate.CAPTURE_FORMAT:
            return date.isoformat(timespec="milliseconds")
        if pattern == generate.WAKE_FORMAT:
            return date.isoformat(timespec="seconds")
        formats = {"HH:mm": "%H:%M", "yyyy-MM-dd": "%Y-%m-%d", "EEEE": "%A", "yyyy-MM-dd'T'HH:mm": "%Y-%m-%dT%H:%M"}
        return date.strftime(formats[pattern])

    def condition(self, parameters):
        source = parameters["WFInput"]
        left = self.resolve(source)
        operator = parameters["WFCondition"]
        if operator in (100, 101):
            present = left is not None and left != "" and left != []
            return present if operator == 100 else not present
        right = self.resolve(next((parameters[key] for key in ("WFNumberValue", "WFDate", "WFConditionalActionString") if key in parameters), None))
        if operator == 99:
            return right in left
        if operator == 4:
            return left == right
        if operator == 5:
            return left != right
        if operator == 2:
            return left > right
        if operator == 0:
            return left < right
        raise AssertionError("Unknown condition")

    def http(self, parameters):
        if self.network_error:
            raise OSError("Mock local network unavailable")
        url = self.resolve(parameters["WFURL"])
        if parameters["WFHTTPMethod"] == "POST":
            assert parameters["WFHTTPBodyType"] == "File"
            assert self.resolve(parameters["WFHTTPHeaders"]) == {"Content-Type": "application/json"}
            body = json.loads(self.resolve(parameters["WFRequestVariable"]))
            self.posts.append((url, body))
            self.last_body = body
            if self.api_error:
                return {"error": self.api_error}
            return {"job": 7, "confirmed": False, "resultUrl": self.receipt_url}
        self.reads.append(url)
        if url == BASE + generate.SYNC_PATH:
            return {"version": 2, "supported": True, "configurationValid": True, "clockValid": True, **self.status_overrides}
        if url == BASE + generate.PROFILE_PATH:
            return {"version": 2, "supported": True, "revision": 11, "enabled": False, "profile": deepcopy(PROFILE)}
        assert url == BASE + RESULT_URL, "A receipt must never redirect a read elsewhere"
        self.polls += 1
        return {"version": 2, "job": 7, "confirmed": self.polls > self.pending_polls, "error": "", "enabled": True,
                **self.last_body, **self.result_overrides}

    def action(self, action):
        name = action["WFWorkflowActionIdentifier"]
        raw = action["WFWorkflowActionParameters"]
        parameters = {key: self.resolve(value) for key, value in raw.items()}
        if name == generate.ALARM_ACTION:
            if self.clock_error:
                raise OSError("Mock Clock read failed")
            self.now += timedelta(seconds=self.read_delay)
            return deepcopy(self.alarms)
        name = name.removeprefix("is.workflow.actions.")
        if name in ("comment", "delay"):
            return None
        if name == "gettext":
            return parameters["WFTextActionText"]
        if name == "number":
            return parameters["WFNumberActionNumber"]
        if name == "setvariable":
            self.variables[parameters["WFVariableName"]] = parameters["WFInput"]
            return parameters["WFInput"]
        if name == "detect.text":
            return self.as_text(parameters["WFInput"])
        if name == "text.trimwhitespace":
            return self.as_text(parameters["WFInput"]).strip()
        if name == "text.replace":
            return re.sub(parameters["WFReplaceTextFind"], parameters["WFReplaceTextReplace"],
                          self.as_text(parameters["WFInput"]), flags=0 if parameters["WFReplaceTextCaseSensitive"] else re.I)
        if name == "text.match":
            return re.findall(parameters["WFMatchTextPattern"], self.as_text(parameters["text"]),
                              flags=0 if parameters["WFMatchTextCaseSensitive"] else re.I)
        if name == "text.combine":
            source = parameters["text"]
            return "\n".join(map(self.as_text, source)) if isinstance(source, list) else self.as_text(source)
        if name == "date":
            return self.now if parameters["WFDateActionMode"] == "Current Date" else self.date(parameters["WFDateActionDate"])
        if name == "format.date":
            return self.format_date(parameters["WFDate"], parameters["WFDateFormat"])
        if name == "adjustdate":
            return self.date(parameters["WFDate"]) + timedelta(days=float(parameters["WFDuration"]["Magnitude"]))
        if name == "calculateexpression":
            match = re.fullmatch(r"([0-9]+) - 1", parameters["WFExpression"])
            assert match
            return int(match[1]) - 1
        if name == "getvalueforkey":
            source = parameters["WFInput"]
            return list(source) if parameters["WFGetDictionaryValueType"] == "All Keys" else source.get(parameters["WFDictionaryKey"])
        if name == "downloadurl":
            return self.http(raw)
        if name == "detect.dictionary":
            source = parameters["WFInput"]
            return source if isinstance(source, dict) else json.loads(source)
        if name == "notification":
            self.messages.append(parameters["WFNotificationActionBody"])
            return None
        if name in ("showresult", "previewdocument"):
            self.output = parameters["Text" if name == "showresult" else "WFInput"]
            return self.output
        if name == "alert":
            if self.cancel_alert:
                raise Stop()
            return None
        if name == "output":
            self.output = parameters["WFOutput"]
            raise Stop()
        if name == "exit":
            raise Stop()
        raise AssertionError("Unsupported mock action: " + name)

    def block(self, start, end):
        index = start
        while index < end:
            action = self.actions[index]
            parameters = action["WFWorkflowActionParameters"]
            if index in self.ends:
                finish = self.ends[index]
                if action["WFWorkflowActionIdentifier"].endswith("conditional"):
                    middle = self.elses.get(index, finish)
                    if self.condition(parameters):
                        self.block(index + 1, middle)
                    elif middle < finish:
                        self.block(middle + 1, finish)
                else:
                    old = {name: self.variables.get(name) for name in ("Repeat Item", "Repeat Index")}
                    if "WFInput" in parameters:
                        items = self.resolve(parameters["WFInput"])
                    else:
                        items = range(int(self.resolve(parameters["WFRepeatCount"])))
                    for count, item in enumerate(items, start=1):
                        self.variables["Repeat Item"], self.variables["Repeat Index"] = item, count
                        self.block(index + 1, finish)
                    self.variables.update(old)
                index = finish + 1
            else:
                self.outputs[parameters["UUID"]] = self.action(action)
                index += 1

    def run(self):
        try:
            self.block(0, len(self.actions))
        except Stop:
            pass
        return self


class ShortcutsTests(unittest.TestCase):
    def sync(self, alarms=(), now=NOW, live=1, **changes):
        runtime = Runtime(configured(generate.build_sync(), live), alarms, now)
        for key, value in changes.items():
            setattr(runtime, key, value)
        return runtime.run()

    def test_selects_only_earliest_enabled_exact_wled_label(self):
        runtime = self.sync([alarm("ordinary", "05:00"), alarm("WLED disabled", "04:00", False),
                             alarm("wled lowercase", "03:00"), alarm("Morning WLED", "08:00"), alarm()])
        self.assertEqual(len(runtime.posts), 1)
        url, payload = runtime.posts[0]
        self.assertEqual(url, BASE + generate.SYNC_PATH)
        self.assertEqual(set(payload), {"capturedAt", "wakeAt"})
        self.assertEqual(payload["wakeAt"], "2026-11-09T07:00:00+01:00")
        self.assertEqual(payload["capturedAt"], NOW.isoformat(timespec="milliseconds"))
        self.assertIn("WLED Work", runtime.output)
        self.assertNotIn("WFSerializationType", runtime.messages[-1])

    def test_passed_one_shot_becomes_tomorrow(self):
        now = NOW.replace(hour=8)
        runtime = self.sync([alarm()], now)
        self.assertEqual(runtime.posts[0][1]["wakeAt"], "2026-11-09T07:00:00+01:00")

    def test_future_time_today_is_not_shifted_to_tomorrow(self):
        runtime = self.sync([alarm(time="23:30")])
        self.assertEqual(runtime.posts[0][1]["wakeAt"], "2026-11-08T23:30:00+01:00")

    def test_german_repetition_and_weekly_wrap(self):
        now = NOW.replace(day=9, hour=8)  # Monday, after the alarm.
        runtime = self.sync([alarm(repeat=["Montag"])], now)
        self.assertEqual(runtime.posts[0][1]["wakeAt"], "2026-11-16T07:00:00+01:00")
        runtime = self.sync([alarm(repeat=["Tue.", "Donnerstag"])])
        self.assertEqual(runtime.posts[0][1]["wakeAt"], "2026-11-10T07:00:00+01:00")

    def test_repeat_date_beats_sorting_by_clock_hours(self):
        runtime = self.sync([alarm("WLED Friday", "05:00", repeat=["Friday"]), alarm("WLED Monday", "08:00", repeat=["Monday"])])
        self.assertEqual(runtime.posts[0][1]["wakeAt"], "2026-11-09T08:00:00+01:00")

    def test_summary_repetition(self):
        for summary, expected in [("Täglich", "2026-11-09"), ("Weekdays", "2026-11-09"), ("Am Wochenende", "2026-11-14"), ("Nie", "2026-11-09")]:
            with self.subTest(summary=summary):
                runtime = self.sync([alarm(repeat=[summary])])
                self.assertTrue(runtime.posts[0][1]["wakeAt"].startswith(expected))

    def test_future_dst_offset_comes_from_wake_date(self):
        now = datetime(2026, 3, 28, 22, 0, tzinfo=ZONE)
        runtime = self.sync([alarm()], now)
        self.assertEqual(runtime.posts[0][1]["wakeAt"], "2026-03-29T07:00:00+02:00")

    def test_nonexistent_dst_time_is_not_guessed(self):
        now = datetime(2026, 3, 28, 22, 0, tzinfo=ZONE)
        runtime = self.sync([alarm(time="02:30", repeat=["Sunday"])], now)
        self.assertEqual(runtime.posts, [])
        self.assertIn("DST gap", runtime.messages[-1])

    def test_successful_empty_or_disabled_read_is_an_explicit_clear(self):
        for alarms in ([], [alarm(enabled=False)], [alarm(label="ordinary")]):
            runtime = self.sync(alarms)
            self.assertIsNone(runtime.posts[0][1]["wakeAt"])
            self.assertEqual(set(runtime.posts[0][1]), {"capturedAt", "wakeAt"})

    def test_capture_precedes_clock_read_and_network_wait(self):
        runtime = self.sync([alarm()], read_delay=30, pending_polls=3)
        self.assertEqual(runtime.posts[0][1]["capturedAt"], NOW.isoformat(timespec="milliseconds"))
        self.assertEqual(runtime.polls, 4)

    def test_unknown_enabled_repeat_or_missing_time_aborts_without_post(self):
        missing_enabled, missing_time = alarm(), alarm()
        del missing_enabled["Is Enabled"]
        del missing_time["Time"]
        for item in (missing_enabled, missing_time, alarm(enabled="unavailable"), alarm(repeat=["unknown"]), alarm(repeat=["Monday-Friday"])):
            runtime = self.sync([item])
            self.assertEqual(runtime.posts, [])
            self.assertTrue(runtime.messages)

    def test_native_clock_and_network_errors_do_not_clear(self):
        for setting in ("clock_error", "network_error"):
            runtime = Runtime(configured(generate.build_sync()), [alarm()])
            setattr(runtime, setting, True)
            with self.assertRaises(OSError):
                runtime.run()
            self.assertEqual(runtime.posts, [])

    def test_not_ready_and_preview_never_post(self):
        runtime = self.sync([alarm()], live=0)
        self.assertEqual(runtime.posts, [])
        self.assertEqual(runtime.reads, [])
        self.assertIn("Preview only", runtime.output)
        for key in ("supported", "configurationValid", "clockValid"):
            runtime = self.sync([alarm()], status_overrides={key: False})
            self.assertEqual(runtime.posts, [])

    def test_202_receipt_is_not_success_and_polling_is_bounded(self):
        runtime = self.sync([alarm()], pending_polls=100)
        self.assertEqual(len(runtime.posts), 1)
        self.assertEqual(runtime.polls, 12)
        self.assertIsNone(runtime.output)
        self.assertIn("No durable confirmation", runtime.messages[-1])

    def test_errors_conflicts_and_reboot_receipts_do_not_claim_success(self):
        for overrides in ({"error": "stale_sync"}, {"error": "job_from_other_boot"}, {"error": "sync_rate_limited"}, {"job": 8}, {"version": 1}):
            runtime = self.sync([alarm()], result_overrides=overrides)
            self.assertIsNone(runtime.output)
            self.assertEqual(len(runtime.posts), 1)  # Never retry an old reading with a new capture.
            self.assertEqual(runtime.polls, 1)

    def test_receipt_path_cannot_redirect_to_another_host_or_endpoint(self):
        for path in ("https://example.com/collect", "/wecker/result?job=7", RESULT_URL + "&next=https://example.com", ""):
            runtime = self.sync([alarm()], receipt_url=path)
            self.assertEqual(runtime.polls, 0)
            self.assertIsNone(runtime.output)

    def test_setup_preserves_profile_and_uses_profile_revision(self):
        runtime = Runtime(configured(generate.build_setup())).run()
        self.assertEqual(runtime.posts, [(BASE + generate.PROFILE_PATH, {"revision": 11, "enabled": True, "profile": PROFILE})])

    def test_explicit_clear_and_cancel(self):
        document = generate.build_clear().document()
        alert = next(action["WFWorkflowActionParameters"] for action in document["WFWorkflowActions"]
                     if action["WFWorkflowActionIdentifier"] == "is.workflow.actions.alert")
        self.assertIn("already running light alarm will continue", alert["WFAlertActionMessage"])
        self.assertIn("WLED Stop", alert["WFAlertActionMessage"])
        runtime = Runtime(configured(generate.build_clear())).run()
        self.assertIsNone(runtime.posts[0][1]["wakeAt"])
        runtime = Runtime(configured(generate.build_clear()))
        runtime.cancel_alert = True
        runtime.run()
        self.assertEqual(runtime.posts, [])

    def test_check_and_status_are_read_only(self):
        runtime = Runtime(configured(generate.build_sync(True)), [alarm()]).run()
        self.assertIn("2026-11-09T07:00", runtime.output)
        self.assertEqual(runtime.posts + runtime.reads, [])
        runtime = Runtime(configured(generate.build_status())).run()
        self.assertEqual(runtime.posts, [])
        self.assertEqual(runtime.reads, [BASE + generate.SYNC_PATH])

    def test_all_templates_are_inspectable_native_plists_and_do_not_edit_clock(self):
        for shortcut in generate.build_all():
            document = shortcut.document()
            self.assertEqual(plistlib.loads(plistlib.dumps(document)), document)
            Runtime(document)  # Also checks balanced native control-flow groups.
            for action in document["WFWorkflowActions"]:
                identifier = action["WFWorkflowActionIdentifier"]
                self.assertTrue(identifier.startswith("is.workflow.actions.") or identifier == generate.ALARM_ACTION)
                self.assertNotIn("/wecker.json", json.dumps(action))
                self.assertNotIn("/wecker/control", json.dumps(action))
            if shortcut.name == "WLED Alarm Sync":
                question = next(item for item in document["WFWorkflowImportQuestions"] if item["ParameterKey"] == "WFNumberActionNumber")
                self.assertEqual(document["WFWorkflowActions"][question["ActionIndex"]]["WFWorkflowActionParameters"]["WFNumberActionNumber"], 0)

    def test_utf16_variable_ranges_and_private_address_validation(self):
        reference = generate.variable("example")
        runtime = Runtime(configured(generate.build_status()))
        runtime.variables["example"] = "value"
        self.assertEqual(runtime.resolve(generate.text("🌅 ", reference, " / ", reference)), "🌅 value / value")
        for address in (BASE, "http://10.0.0.32", "http://172.16.0.32"):
            self.assertTrue(re.fullmatch(generate.BASE_PATTERN, address))
        for address in ("https://192.168.1.1", "http://example.com", "http://127.0.0.1", "http://8.8.8.8", "http://10.0.0.999", BASE + "/proxy"):
            self.assertFalse(re.fullmatch(generate.BASE_PATTERN, address))

    def test_signing_failure_keeps_all_sources_and_reports_unsigned_manifest(self):
        with tempfile.TemporaryDirectory(prefix="wled-ios-shortcuts-") as temporary:
            with patch.object(sys, "argv", ["generate.py", "--output", temporary, "--sign"]), \
                 patch.object(generate.subprocess, "run", side_effect=subprocess.CalledProcessError(1, ["shortcuts", "sign"])), \
                 redirect_stderr(StringIO()):
                self.assertEqual(generate.main(), 1)
            directory = generate.Path(temporary)
            self.assertEqual(len(list((directory / "unsigned").glob("*.shortcut"))), 5)
            self.assertFalse(json.loads((directory / "manifest.json").read_text())["signed"])
            self.assertTrue((directory / "Sign on Mac.command").stat().st_mode & 0o100)
            self.assertTrue((directory / "INSTALL.txt").is_file())
            with zipfile.ZipFile(directory / "WLED Shortcuts - Mac signing kit.zip") as archive:
                self.assertEqual(len(archive.namelist()), 7)
                self.assertEqual(sum("/unsigned/" in name for name in archive.namelist()), 5)
                self.assertNotIn("manifest.json", " ".join(archive.namelist()))


if __name__ == "__main__":
    unittest.main()
